import heapq

def match(orders):
    book = {}  # id -> dict with side, price, qty, time, active
    buy_heap = []  # (-price, time, id)
    sell_heap = []  # (price, time, id)
    trades = []
    time_counter = 0

    def pop_valid(heap):
        # pop entries from top that are invalid (cancelled/filled), return top valid entry without removing it, or None
        while heap:
            entry = heap[0]
            oid = entry[2]
            info = book.get(oid)
            if info is None or not info['active'] or info['qty'] <= 0:
                heapq.heappop(heap)
                continue
            return entry
        return None

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            info = book.get(oid)
            if info is not None and info['active'] and info['qty'] > 0:
                info['active'] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        elif typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            continue

        time_counter += 1
        arrival_time = time_counter

        remaining = qty

        if side == 'buy':
            opp_heap = sell_heap
        else:
            opp_heap = buy_heap

        while remaining > 0:
            top = pop_valid(opp_heap)
            if top is None:
                break
            resting_price = top[0] if opp_heap is sell_heap else -top[0]
            resting_time = top[1]
            resting_id = top[2]
            resting_info = book[resting_id]

            # price condition
            if typ == 'market':
                ok = True
            else:
                if side == 'buy':
                    ok = resting_price <= price
                else:
                    ok = resting_price >= price
            if not ok:
                break

            # pop it for real now
            heapq.heappop(opp_heap)

            trade_qty = min(remaining, resting_info['qty'])
            if side == 'buy':
                buy_id = oid
                sell_id = resting_id
            else:
                buy_id = resting_id
                sell_id = oid

            trades.append([buy_id, sell_id, resting_price, trade_qty])

            remaining -= trade_qty
            resting_info['qty'] -= trade_qty

            if resting_info['qty'] > 0:
                # push back onto heap
                heapq.heappush(opp_heap, top)
            else:
                resting_info['active'] = False

        # handle remainder
        if remaining > 0:
            if typ == 'limit':
                book[oid] = {'side': side, 'price': price, 'qty': remaining, 'time': arrival_time, 'active': True}
                if side == 'buy':
                    heapq.heappush(buy_heap, (-price, arrival_time, oid))
                else:
                    heapq.heappush(sell_heap, (price, arrival_time, oid))
            else:
                # ioc or market: discard remainder
                pass
        else:
            # fully filled, nothing to add
            pass

    return trades

